public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        return result;
    }
    // copy and sort
    int[] arr = nums.clone();
    java.util.Arrays.sort(arr);
    int n = arr.length;
    // helper list to add each permutation
    do {
        java.util.ArrayList<Integer> perm = new java.util.ArrayList<>(n);
        for (int val : arr) {
            perm.add(val);
        }
        result.add(perm);
        // next permutation
        int i = n-1;
        while (i>0 && arr[i-1] > arr[i]) i--;
        if (i <= 0) break;
        int j = n-1;
        while (arr[i-1] >= arr[j]) j--;
        int temp = arr[i-1];
        arr[i-1] = arr[j];
        arr[j] = temp;
        int l = i, r = n-1;
        while (l < r) {
            int t = arr[l];
            arr[l] = arr[r];
            arr[r] = t;
            l++; r--;
        }
    } while (true);
    return result;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
