    }
    // Find the shortest string to minimize candidate substrings
    int minIndex = 0;
    for (int i = 1; i < strings.size(); i++) {
        if (strings.get(i).length() < strings.get(minIndex).length()) {
            minIndex = i;
        }
    }
    String minStr = strings.get(minIndex);
    if (minStr.isEmpty()) {
        return 0;
    }
    int minLen = minStr.length();
    // Iterate lengths from longest to shortest
    for (int len = minLen; len > 0; len--) {
        java.util.Set<String> candidates = new java.util.HashSet<>();
        // generate all substrings of current length from the shortest string
        for (int start = 0; start + len <= minStr.length(); start++) {
            candidates.add(minStr.substring(start, start + len));
        }
        // check each candidate
        for (String cand : candidates) {
            String rev = new StringBuilder(cand).reverse().toString();
