            continue;
        }
        for (int c = 0; c < grid[r].length; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                count++;
                // start DFS/BFS from (r,c)
                stack.push(new int[]{r, c});
                visited[r][c] = true;
                while (!stack.isEmpty()) {
                    int[] pos = stack.pop();
                    int cr = pos[0];
