public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Number of triangles must be non-negative");
    }
    if (N == 0) {
        return 1; // No triangles, the plane is one region
    }
    long regions = 2L + 3L * N * (N - 1);
    if (regions > Integer.MAX_VALUE) {
        throw new ArithmeticException("Result exceeds maximum int value");
    }
    return (int) regions;
}

public static int maxRegions(int N) {
    if (N <= 0) {
        return 1; // No triangles, one unbounded region
    }
    long regions = 3L * N * N - 3L * N + 2;
    // Clamp to Integer.MAX_VALUE to avoid overflow for extremely large N
    return (int) Math.min(regions, Integer.MAX_VALUE);
}

