    if (startNode < 0 || startNode >= n || endNode < 0 || endNode >= n) {
        return "cannot be travelled";
    }
    if (startNode == endNode) {
        return "can be travelled";
    }

    // Build adjacency list
    List<List<Integer>> graph = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        graph.add(new ArrayList<>());
    }
    for (int[] edge : paths) {
        if (edge == null || edge.length < 2) {
            continue; // skip invalid entries
        }
        int u = edge[0];
        int v = edge[1];
        if (u < 0 || u >= n || v < 0 || v >= n) {
            continue; // skip out-of-range edges
        }
        graph.get(u).add(v);
        graph.get(v).add(u);
    }

    // Breadth-First Search to check reachability
    boolean[] visited = new boolean[n];
    Queue<Integer> queue = new ArrayDeque<>();
    queue.offer(startNode);
    visited[startNode] = true;

    while (!queue.isEmpty()) {
        int current = queue.poll();
        for (int neighbor : graph.get(current)) {
            if (!visited[neighbor]) {
                if (neighbor == endNode) {
                    return "can be travelled";
                }
                visited[neighbor] = true;
                queue.offer(neighbor);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || start.length == 0 || end.length == 0) {
        throw new IllegalArgumentException("Start and end coordinates must be non‑empty.");
    }

    int dim = start.length;
    // Helper to convert coordinate array to a unique string key
    java.util.function.Function<int[], String> coordKey = coord -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coord[i]);
        }
        return sb.toString();
    };

    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();

    if (paths != null) {
        for (int[] path : paths) {
            if (path == null || path.length != 2 * dim) {
                // Skip malformed path entries
                continue;
            }
            int[] from = java.util.Arrays.copyOfRange(path, 0, dim);
            int[] to   = java.util.Arrays.copyOfRange(path, dim, 2 * dim);
            String fromKey = coordKey.apply(from);
            String toKey   = coordKey.apply(to);

            graph.computeIfAbsent(fromKey, k -> new java.util.ArrayList<>()).add(toKey);
            graph.computeIfAbsent(toKey, k   -> new java.util.ArrayList<>()).add(fromKey);
        }
    }

    String startKey = coordKey.apply(start);
    String endKey   = coordKey.apply(end);

    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();

    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
