        int day   = Integer.parseInt(parts[1]);   // 1–31
        int year  = Integer.parseInt(parts[2]);   // e.g., 1997

        // Prepare month and weekday names
        String[] monthNames = {
            "January", "February", "March", "April", "May", "June",
            "July", "August", "September", "October", "November", "December"
        };

        String[] weekdayNames = {
            "Sunday", "Monday", "Tuesday", "Wednesday",
            "Thursday", "Friday", "Saturday"
        };

        // Use Calendar to determine the weekday
        java.util.Calendar calendar = new java.util.GregorianCalendar(year, month - 1, day);
        int dayOfWeekIndex = calendar.get(java.util.Calendar.DAY_OF_WEEK); // 1 = Sunday

        String monthName = monthNames[month - 1];
        String weekdayName = weekdayNames[dayOfWeekIndex - 1];

        // Format day without leading zero
        return monthName + " " + day + ", " + year + " is a " + weekdayName;
    } catch (Exception e) {
        return "Invalid date";
    }
}

