public double trimMean(int[] arr) {
    if (arr == null || arr.length == 0) {
        return 0.0;
    }
    int n = arr.length;
    int removeCount = (int) (n * 0.05);
    // If removal amount is zero (array too small), simply compute average of all elements
    if (removeCount == 0) {
        long total = 0;
        for (int val : arr) {
            total += val;
        }
        return total / (double) n;
    }
    // Sort the array to remove smallest and largest 5%
    java.util.Arrays.sort(arr);
    long sum = 0L;
    for (int i = removeCount; i < n - removeCount; i++) {
        sum += arr[i];
    }
    int remaining = n - 2 * removeCount;
    return sum / (double) remaining;
}

public double trimMean(int[] arr) {
    int n = arr.length;
    int trim = (int) Math.floor(n * 0.05);
    java.util.Arrays.sort(arr);
    long sum = 0;
    for (int i = trim; i < n - trim; i++) {
        sum += arr[i];
    }
    return sum / (double) (n - 2 * trim);
}

