    int[] sorted = arr.clone();
    java.util.Arrays.sort(sorted);
    long sum = 0;
    for (int i = trimCount; i < n - trimCount; i++) {
        sum += sorted[i];
    }
    int remaining = n - 2 * trimCount;
    return (double)sum / remaining;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || k <= 0) {
        // Invalid input: cannot perform pairing.
        return false;
    }
    int n = arr.length;
    if (n % 2 != 0) {
        // Odd number of elements cannot be fully paired.
        return false;
    }
    // Count frequencies of remainders modulo k.
    int[] freq = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k; // Ensure non‑negative remainder
        freq[rem]++;
    }
    // Remainder 0 elements must be paired among themselves.
    if (freq[0] % 2 != 0) {
        return false;
    }
    // For even k, remainder k/2 elements must also pair among themselves.
    if (k % 2 == 0 && freq[k / 2] % 2 != 0) {
        return false;
    }
    // For the remaining remainders, each r must match k - r.
    for (int r = 1; r < k - r; r++) {
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    return true;
}

