public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    if (n == 1) {
        return 0;
    }
    int first = cost[0];
    int second = cost[1];
    for (int i = 2; i < n; i++) {
        int current = Math.min(first, second) + cost[i];
        first = second;
        second = current;
    }
    return Math.min(first, second);
}

