    // If there are 0 or 1 steps, we can start from the top with no cost.
    if (n <= 1) {
        return 0;
    }
    // dp[0] = cost[0], dp[1] = cost[1]
    int prev2 = cost[0];
    int prev1 = cost[1];
    if (n == 2) {
        return Math.min(prev2, prev1);
    }
    int current = 0;
    for (int i = 2; i < n; i++) {
        current = Math.min(prev1, prev2) + cost[i];
        prev2 = prev1;
        prev1 = current;
    }
    // Minimum cost to reach the top is either from the last step or the second last step.
    return Math.min(prev1, prev2);
}

