    return dp[n];
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Cost array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    // dp[i] represents the minimum cost to reach step i
    // We only need the last two values at any time
    int dpPrev2 = 0; // dp[0]
    int dpPrev1 = 0; // dp[1]
    for (int i = 2; i <= n; i++) {
        int costFromPrevStep1 = dpPrev1 + cost[i - 1];
        int costFromPrevStep2 = dpPrev2 + cost[i - 2];
        int dpCurr = Math.min(costFromPrevStep1, costFromPrevStep2);
        dpPrev2 = dpPrev1;
        dpPrev1 = dpCurr;
    }
    return dpPrev1;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Cost array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0; // no steps, already at the top
    }
    if (n == 1) {
        return cost[0]; // only one step, must pay its cost
    }
    // dpPrevPrev holds dp[i-2], dpPrev holds dp[i-1]
    int dpPrevPrev = cost[0];
    int dpPrev = cost[1];
    int dp = 0;
    for (int i = 2; i < n; i++) {
        dp = cost[i] + Math.min(dpPrev, dpPrevPrev);
        dpPrevPrev = dpPrev;
        dpPrev = dp;
    }
    return Math.min(dpPrev, dpPrevPrev);
}

