public boolean hasAllCodes(String s, int k) {
    if (s == null || k <= 0) {
        return false;
    }
    if (k > s.length()) {
        return false;
    }
    int totalCodes = 1 << k;
    Set<Integer> seen = new HashSet<>(totalCodes);
    int mask = totalCodes - 1;
    int code = 0;
    // Build the first window
    for (int i = 0; i < k; i++) {
        code = (code << 1) | (s.charAt(i) - '0');
    }
    seen.add(code);
    // Slide through the string
    for (int i = k; i < s.length(); i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        seen.add(code);
    }
    return seen.size() == totalCodes;
}

public boolean hasAllCodes(String s, int k) {
    if (s == null) {
        return false;
    }
    if (k <= 0) {
        return true;
    }
    int n = s.length();
    if (n < k) {
        return false;
    }
    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int mask = 0;
    // Build initial mask
    for (int i = 0; i < k; i++) {
        char c = s.charAt(i);
        if (c != '0' && c != '1') {
            return false;
        }
        mask = (mask << 1) | (c - '0');
    }
    seen[mask] = true;
    int seenCount = 1;
    int maskMask = total - 1; // keep only k bits
    for (int i = k; i < n; i++) {
        char c = s.charAt(i);
        if (c != '0' && c != '1') {
            return false;
        }
        mask = ((mask << 1) & maskMask) | (c - '0');
        if (!seen[mask]) {
            seen[mask] = true;
            seenCount++;
            if (seenCount == total) {
                return true;
            }
        }
    }
    return seenCount == total;
}

public boolean hasAllCodes(String s, int k) {
    // Handle invalid input gracefully
    if (s == null || k <= 0) {
