public boolean hasAllCodes(String s, int k) {
    // Validate input
    if (s == null || k < 0) {
        return false;
    }
    // For k == 0, the only binary string of length 0 ("") is trivially a substring
    if (k == 0) {
        return true;
    }

    int n = s.length();
    // If s is shorter than the number of possible k-length binary strings, it's impossible
    int totalCodes = 1 << k;
    if (n < totalCodes) {
        return false;
    }

    boolean[] seen = new boolean[totalCodes];
    int mask = totalCodes - 1;

    // Build the integer value of the first substring of length k
    int cur = 0;
    for (int i = 0; i < k; i++) {
        cur = (cur << 1) | (s.charAt(i) - '0');
    }
    seen[cur] = true;

    // Use a sliding window to compute all subsequent k-length substring codes
    for (int i = k; i < n; i++) {
        cur = ((cur << 1) & mask) | (s.charAt(i) - '0');
        seen[cur] = true;
    }

    // Verify that every possible code was seen
    for (boolean flag : seen) {
        if (!flag) {
            return false;
        }
    }
    return true;
}

