        return 0;
    }

    // Generate Fibonacci numbers up to k.
    int[] fib = new int[50];
    fib[0] = 1;
    fib[1] = 1;
    int fibCount = 2;

    while (true) {
        int next = fib[fibCount - 1] + fib[fibCount - 2];
        if (next > k) {
            break;
        }
        if (fibCount == fib.length) {
            int[] newFib = new int[fib.length * 2];
            System.arraycopy(fib, 0, newFib, 0, fib.length);
            fib = newFib;
        }
        fib[fibCount] = next;
        fibCount++;
    }

    int count = 0;
    int remaining = k;
    for (int i = fibCount - 1; i >= 0 && remaining > 0; i--) {
        if (fib[i] <= remaining) {
            remaining -= fib[i];
            count++;
        }
    }

    return count;
}

public int kthFactor(int n, int k) {
    java.util.List<Integer> factors = new java.util.ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            factors.add(i);
            int other = n / i;
            if (other != i) {
                factors.add(other);
            }
        }
    }
    java.util.Collections.sort(factors);
    return (k > factors.size()) ? -1 : factors.get(k - 1);
}

