public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) return -1;
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();

    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (other != i) {
                large.add(other);
            }
        }
    }

    int totalFactors = small.size() + large.size();
    if (k > totalFactors) return -1;

    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        int idxInLarge = k - small.size() - 1; // 0-based index in ascending order of large factors
        int j = large.size() - 1 - idxInLarge;   // reverse index
        return large.get(j);
    }
}

public int kthFactor(int n, int k) {
    java.util.List<Integer> factors = new java.util.ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
            if (i != n / i) {
                factors.add(n / i);
            }
        }
    }
    java.util.Collections.sort(factors);
    return k <= factors.size() ? factors.get(k - 1) : -1;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();

    for (int i = 1; (long) i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (other != i) {
                large.add(other);
            }
        }
    }

    java.util.Collections.reverse(large);

    java.util.List<Integer> allFactors = new java.util.ArrayList<>(small);
    allFactors.addAll(large);

    if (k > allFactors.size()) {
        return -1;
    }
    return allFactors.get(k - 1);
}

public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char current = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char top = stack.charAt(len - 1);
            // Check if current and top are opposite case of same letter
            if (Math.abs(current - top) == 32) {
                stack.deleteCharAt(len - 1); // remove the bad pair
                continue;
            }
        }
        stack.append(current);
    }
    return stack.toString();
}

