        // Check if the last character in the stack forms a bad pair with the current character
        if (stackSize > 0) {
            char top = stack.charAt(stackSize - 1);
            if (Math.abs(top - current) == 32) { // opposite case of the same letter
                stack.deleteCharAt(stackSize - 1); // remove the bad pair
