        char current = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char last = stack.charAt(len - 1);
            if (Character.toLowerCase(current) == Character.toLowerCase(last) &&
                current != last) { // opposite case, same letter
                stack.setLength(len - 1); // pop
                continue;
            }
        }
        stack.append(current); // push
    }
    return stack.toString();
}

