public String getSmallestString(int n, int k) {
    if (n <= 0) {
        throw new IllegalArgumentException("Length n must be positive");
    }
    if (k < n || k > 26 * n) {
        throw new IllegalArgumentException("k is out of valid range");
    }
    char[] res = new char[n];
    for (int i = 0; i < n; i++) {
        res[i] = 'a';
    }
    int remaining = k - n;
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining);
        res[i] = (char) (res[i] + add);
        remaining -= add;
    }
    return new String(res);
}

public String getSmallestString(int n, int k) {
    if (n <= 0) return "";
    // Check for impossible cases
    if (k < n || (long)k > 26L * n) return "";
    char[] result = new char[n];
    // Start with all 'a's
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    int diff = k - n; // how much we need to add beyond the base 'a's
    // Increase letters from the rightmost position
    for (int i = n - 1; i >= 0 && diff > 0; i--) {
        int add = Math.min(25, diff); // each char can increase from 'a'(1) to 'z'(26) -> max +25
        result[i] = (char) ('a' + add);
        diff -= add;
    }
    return new String(result);
}

