public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int ones = 0, twos = 0;
    for (int num : nums) {
        int newOnes = (ones ^ num) & ~twos;
        int newTwos = (twos ^ num) & ~newOnes;
        ones = newOnes;
        twos = newTwos;
    }
    return ones;
}

public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int[] bitCounts = new int[32];
    for (int num : nums) {
        for (int i = 0; i < 32; i++) {
            bitCounts[i] += (num >> i) & 1;
        }
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        if ((bitCounts[i] % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

