public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;

    boolean[][] adj = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            int sum = A[i] + A[j];
            int sqrt = (int) Math.sqrt(sum);
            if (sqrt * sqrt == sum) {
                adj[i][j] = true;
            }
        }
    }

    int maxMask = 1 << n;
    int[][] dp = new int[maxMask][n];
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }

    for (int mask = 1; mask < maxMask; mask++) {
        for (int last = 0; last < n; last++) {
            int cur = dp[mask][last];
            if (cur == 0) continue;
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) == 0 && adj[last][next]) {
                    dp[mask | (1 << next)][next] += cur;
                }
            }
        }
    }

    int fullMask = maxMask - 1;
    long total = 0;
    for (int last = 0; last < n; last++) {
        total += dp[fullMask][last];
    }
    return (int) total;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    java.util.Arrays.sort(A);

    int maxSum = 0;
    for (int i = 0; i < n; i++) {
        if (A[i] > maxSum) maxSum = A[i];
    }
    maxSum = maxSum * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 2; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }

    boolean[][] good = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            int sum = A[i] + A[j];
            if (sum <= maxSum) {
                good[i][j] = isSquare[sum];
            }
        }
    }

    long[][] memo = new long[1 << n][n];
    for (int mask = 0; mask < (1 << n); mask++) {
        for (int j = 0; j < n; j++) {
            memo[mask][j] = -1L;
        }
    }

    return (int) dfs(0, -1, n, good, memo, A);
}

private static long dfs(int mask, int last, int n, boolean[][] good, long[][] memo, int[] A) {
    if (mask == (1 << n) - 1) return 1L;
    if (last != -1 && memo[mask][last] != -1L) return memo[mask][last];

    long total = 0L;
    for (int i = 0; i < n; i++) {
        if ((mask & (1 << i)) != 0) continue;
        if (last != -1 && !good[last][i]) continue;
        if (i > 0 && A[i] == A[i - 1] && (mask & (1 << (i - 1))) == 0) continue;

        total += dfs(mask | (1 << i), i, n, good, memo, A);
    }

    if (last != -1) memo[mask][last] = total;
    return total;
}

