    if (A == null) return 0;
    int n = A.length;
    if (n == 0) return 1;
    java.util.Arrays.sort(A);
    boolean[][] ok = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int sum = A[i] + A[j];
            int r = (int) Math.sqrt(sum);
            ok[i][j] = r * r == sum;
        }
    }
    boolean[] used = new boolean[n];
    int[] ans = new int[1];
    dfs(0, -1, A, ok, used, ans);
    return ans[0];
}

private static void dfs(int depth, int prev, int[] A, boolean[][] ok, boolean[] used, int[] ans) {
    int n = A.length;
    if (depth == n) {
        ans[0]++;
        return;
    }
    for (int i = 0; i < n; i++) {
        if (used[i]) continue;
        if (i > 0 && A[i] == A[i - 1] && !used[i - 1]) continue;
        if (prev != -1 && !ok[prev][i]) continue;
        used[i] = true;
        dfs(depth + 1, i, A, ok, used, ans);
        used[i] = false;
    }
}

