public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    int current = 1;
    for (int i = 0; i < n; i++) {
        result.add(current);
        if (current * 10 <= n) {
            current *= 10;
        } else {
            while (current % 10 == 9 || current + 1 > n) {
                current /= 10;
            }
            current += 1;
        }
    }
    return result;
}

public static List<Integer> lexicalOrder(int n) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (n <= 0) {
        return result;
    }

    int current = 1;
    for (int i = 0; i < n; i++) {
        result.add(current);

        if (current * 10 <= n) {
            // Go deeper
            current *= 10;
        } else {
            // Move to the next number in lexical order
            if (current % 10 != 9 && current + 1 <= n) {
                current += 1;
            } else {
                while ((current / 10) % 10 == 9 || current + 1 > n) {
                    current /= 10;
                }
                current /= 10;
                current += 1;
            }
        }
    }

    return result;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }
    for (int i = 1; i <= 9 && i <= n; i++) {
        dfs(i, n, result);
    }
    return result;
}

private static void dfs(int current, int n, List<Integer> res) {
    if (current > n) {
        return;
    }
    res.add(current);
    for (int i = 0; i <= 9; i++) {
        long next = (long) current * 10 + i;
        if (next > n) {
            break;
        }
        dfs((int) next, n, res);
    }
}

