    List<Integer> result = new ArrayList<>();
    if (n <= 0) {
        return result;
    }

    // Helper recursive function to add numbers in lexicographical order
    java.util.function.Consumer<Long> dfs = new java.util.function.Consumer<Long>() {
        @Override
        public void accept(Long curr) {
            if (curr > n) {
                return;
            }
            result.add(curr.intValue());
            for (int i = 0; i <= 9; i++) {
                long next = curr * 10 + i;
                if (next > n) {
