public static int calculateUniqueSum(int[] nums) {
    // Return 0 for null or empty array to handle invalid input gracefully
    if (nums == null || nums.length == 0) {
        return 0;
    }

    // Use a hashmap to count the frequency of each element
    java.util.HashMap<Integer, Integer> frequency = new java.util.HashMap<>();
    for (int value : nums) {
        // In case something unexpected occurs, catch exceptions quietly
        try {
            frequency.put(value, frequency.getOrDefault(value, 0) + 1);
        } catch (Exception e) {
            // If a counting error occurs, skip the element
            continue;
        }
    }

    // Sum up the elements that appear exactly once
    int uniqueSum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : frequency.entrySet()) {
        if (entry.getValue() == 1) {
            uniqueSum += entry.getKey();
        }
    }

    return uniqueSum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) return 0;
    int sqrt = (int) Math.sqrt(n);
    if (sqrt * sqrt == n) return 1;
    for (int i = 1; i <= sqrt; i++) {
        int remainder = n - i * i;
        int rSqrt = (int) Math.sqrt(remainder);
        if (rSqrt * rSqrt == remainder) return 2;
    }
    int temp = n;
    while (temp % 4 == 0) temp /= 4;
    if (temp % 8 == 7) return 4;
    return 3;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int max = n;
    int[] dp = new int[max + 1];
    for (int i = 1; i <= max; i++) {
        int best = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            best = Math.min(best, dp[i - square] + 1);
        }
        dp[i] = best;
    }
    return dp[max];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] + 1 < dp[i]) {
                dp[i] = dp[i - square] + 1;
            }
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }

    // Generate all perfect squares <= n
    int maxRoot = (int) Math.sqrt(n);
    int[] squares = new int[maxRoot];
    for (int i = 1; i <= maxRoot; i++) {
        squares[i - 1] = i * i;
    }

    int[] dp = new int[n + 1];
    // Use a large initial value (n is the worst-case scenario: all ones)
    for (int i = 1; i <= n; i++) {
        dp[i] = n;
    }
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        for (int square : squares) {
            if (square > i) {
                break;
            }
            dp[i] = Math.min(dp[i], dp[i - square] + 1);
        }
    }

    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non‑negative");
    }
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int candidate = dp[i - j * j] + 1;
            if (candidate < min) {
                min = candidate;
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    StringTokenizer st = new StringTokenizer(s, " ");
    StringBuilder result = new StringBuilder();
    while (st.hasMoreTokens()) {
        String word = st.nextToken();
        for (int i = word.length() - 1; i >= 0; i--) {
            result.append(word.charAt(i));
        }
        if (st.hasMoreTokens()) {
            result.append(' ');
        }
    }
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    int i = 0;
    while (i < s.length()) {
        char c = s.charAt(i);
        if (c == ' ') {
            result.append(' ');
            i++;
        } else {
            int start = i;
            while (i < s.length() && s.charAt(i) != ' ') {
                i++;
            }
            for (int j = i - 1; j >= start; j--) {
                result.append(s.charAt(j));
            }
        }
    }
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            // Reverse the current word and append it
            String reversedWord = word.reverse().toString();
            result.append(reversedWord);
            result.append(' ');
            word.setLength(0); // reset for the next word
        } else {
            word.append(c);
        }
    }
    // Append the last word (after the loop, word may still contain characters)
    String reversedWord = word.reverse().toString();
    result.append(reversedWord);
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();

    for (int i = 0; i < words.length; i++) {
        String w = words[i];
        char[] arr = w.toCharArray();
        int left = 0;
        int right = arr.length - 1;
        while (left < right) {
            char temp = arr[left];
            arr[left] = arr[right];
            arr[right] = temp;
            left++;
            right--;
        }
        result.append(new String(arr));
        if (i < words.length - 1) {
            result.append(' ');
        }
    }
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    int len = s.length();
    for (int i = 0; i <= len; i++) {
        char ch = (i < len) ? s.charAt(i) : ' ';  // sentinel to flush the last word
        if (ch == ' ') {
            // Append reversed word
            for (int j = word.length() - 1; j >= 0; j--) {
                result.append(word.charAt(j));
            }
            word.setLength(0); // clear for next word
            if (i < len) {   // add the space that was found in the original string
                result.append(' ');
            }
        } else {
            word.append(ch);
        }
    }
    return result.toString();
}
